      "file": "languages/tiger/connect_four.tg",
      "code": "const ROWS = 6;\nconst COLS = 7;\nconst EMPTY = \".\";\nconst PLAYERS = [\"X\", \"O\"];\nconst DIGITS = \"0123456789\";\nconst WHITESPACE = \" \\t\\r\\n\";\n\nfunction repeat(text, count) {\n    var out = \"\";\n    for i in range(count) { out += text; }\n    return out;\n}\n\nfunction join(items, separator) {\n    var out = \"\";\n    for i in range(len(items)) {\n        if i > 0 { out += separator; }\n        out += str(items[i]);\n    }\n    return out;\n}\n\nconst BORDER = \"+\" + repeat(\"-\", COLS * 2 - 1) + \"+\";\nconst LABELS = \" \" + join(range(1, COLS + 1), \" \");\nconst HEADER = \"=== Connect Four ===\\n\" + \"Get four of your pieces in a row to win. Columns are numbered 1-7.\\n\";\n\n// board[0] is the bottom row.\nfunction new_board() {\n    var board = [];\n    for row in range(ROWS) {\n        var cells = [];\n        for col in range(COLS) { cells += [EMPTY]; }\n        board += [cells];\n    }\n    return board;\n}\n\nfunction render(board) {\n    var lines = [LABELS, BORDER];\n    cfor (var row = ROWS - 1; row >= 0; row--) { lines += [\"|\" + join(board[row], \" \") + \"|\"]; }\n    lines += [BORDER];\n    return join(lines, \"\\n\");\n}\n\nfunction lowest_empty_row(board, column) {\n    for row in range(ROWS) { if board[row][column] == EMPTY { return row; } }\n    return -1;\n}\n\nfunction four_from(board, player, row, col, row_step, col_step) {\n    for k in range(4) { if board[row + k * row_step][col + k * col_step] != player { return false; } }\n    return true;\n}\n\n// Checks rows, columns, and both diagonals from every starting cell that fits on the board.\nfunction has_four(board, player) {\n    for step in [[0, 1], [1, 0], [1, 1], [-1, 1]] {\n        for row in range(ROWS) {\n            for col in range(COLS) {\n                const last_row = row + 3 * step[0];\n                const fits = last_row >= 0 and last_row < ROWS and col + 3 * step[1] < COLS;\n                if fits and four_from(board, player, row, col, step[0], step[1]) { return true; }\n            }\n        }\n    }\n    return false;\n}\n\nfunction strip(text) {\n    var start = 0;\n    var end = len(text);\n    while start < end and text[start] in WHITESPACE { start++; }\n    while end > start and text[end - 1] in WHITESPACE { end--; }\n    var out = \"\";\n    cfor (var i = start; i < end; i++) { out += text[i]; }\n    return out;\n}\n\n// An optional sign followed by one or more ASCII digits.\nfunction is_whole_number(token) {\n    var start = 0;\n    if len(token) > 0 and (token[0] == \"+\" or token[0] == \"-\") { start = 1; }\n    if start == len(token) { return false; }\n    cfor (var i = start; i < len(token); i++) { if not (token[i] in DIGITS) { return false; } }\n    return true;\n}\n\nfunction write(text) { print(text, end=\"\"); }\n\nfunction prompt(player) { return f\"Player {player}, choose a column (1-7): \"; }\n\n// Returns the zero-based column, or null once input is closed.\nfunction ask_column(board, player) {\n    while true {\n        var line = null;\n        try {\n            line = input(prompt(player));\n        } catch (error) {\n            write(\"\\nInput closed. Goodbye.\\n\");\n            return null;\n        }\n        const token = strip(line);\n        var message = \"\";\n        cif (token == \"\") {\n            message = \"Invalid input: no column entered.\";\n        } celse cif (not is_whole_number(token)) {\n            message = f\"Invalid input: \\\"{token}\\\" is not a whole number.\";\n        } celse {\n            var value = 0;\n            // A number too large to convert is simply out of range.\n            try { value = int(token); } catch (error) { value = COLS + 1; }\n            cif (value < 1 || value > COLS) {\n                message = f\"Invalid input: \\\"{token}\\\" is out of range (1-7).\";\n            } celse cif (lowest_empty_row(board, value - 1) == -1) {\n                message = f\"Column {value} is full.\";\n            } celse {\n                return value - 1;\n            }\n        }\n        write(\"\\n\" + message + \"\\n\");\n    }\n}\n\nfunction main() {\n    const board = new_board();\n    write(HEADER + \"\\n\" + render(board) + \"\\n\");\n    var moves = 0;\n    var player_index = 0;\n    while true {\n        const player = PLAYERS[player_index];\n        const column = ask_column(board, player);\n        if column == null { return 0; }\n        board[lowest_empty_row(board, column)][column] = player;\n        moves++;\n        write(\"\\n\" + render(board) + \"\\n\");\n        if has_four(board, player) {\n            write(f\"Player {player} wins!\\n\");\n            return 0;\n        }\n        if moves == ROWS * COLS {\n            write(\"It's a tie!\\n\");\n            return 0;\n        }\n        player_index = 1 - player_index;\n    }\n}\n\nmain();\n",
